<?php
/** Plugin Name: TEMP PS S1728mp petshop-fbt v1.7.2 (juosta + skanestas). Fazes: 1 dry, 2 deploy, 3 patikra, 9 atgal i v1.7.1 */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1728mp3'])) return; $f=(string)$_GET['ps_s1728mp3']; $r=['v'=>'S1728mp','faze'=>$f,'laikas'=>current_time('mysql')]; @set_time_limit(170);
  $fp=WP_PLUGIN_DIR.'/petshop-fbt/petshop-fbt.php'; $arch=dirname(untrailingslashit(ABSPATH)).'/ps-archyvas'; $bak=$arch.'/petshop-fbt.php.bak_s1728c';
  $SENAS='35370264060cb7eab7f9f16928b9e491'; $NAUJAS='80dc63f500b09381fb05dc3f52bd8c28';
  $B64='';
  $tok=function($code){ try{ token_get_all($code,TOKEN_PARSE); return 'ok'; }catch(Throwable $e){ return 'KLAIDA '.$e->getMessage(); } };
  $hb=function(){ $o=[]; $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>30,'sslverify'=>false]); $o['front']=is_wp_error($x)?$x->get_error_message():wp_remote_retrieve_response_code($x); $y=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat&t='.time()),['timeout'=>30,'sslverify'=>false]); $o['admin_ajax']=is_wp_error($y)?$y->get_error_message():wp_remote_retrieve_response_code($y); return $o; };
  try{
    $new=gzuncompress(base64_decode($B64));
    if($f==='1'){ $r['gyvas_md5']=md5_file($fp); $r['gyvas_sutampa']=($r['gyvas_md5']===$SENAS); $r['naujas_ok']=(md5($new)===$NAUJAS); $r['lint']=$tok($new); $r['bak_yra']=is_file($bak); $r['tema_fn']=function_exists('petshop_free_shipping_progress'); }
    if($f==='2'){
      $cur=md5_file($fp); if($cur!==$SENAS && $cur!==$NAUJAS) throw new Exception('gyvas failas pasikeitė: '.$cur);
      if(md5($new)!==$NAUJAS || $tok($new)!=='ok') throw new Exception('naujas turinys blogas');
      if(!is_file($bak)) copy($fp,$bak); $r['bak_md5']=md5_file($bak);
      file_put_contents($fp,$new); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['md5']=md5_file($fp);
      sleep(2); $r['hb']=$hb();
      if($r['hb']['front']!==200 || $r['hb']['admin_ajax']===500){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['ROLLBACK']=true; $r['hb_po']=$hb(); }
    }
    if($f==='3'){ $L0=ob_get_level(); ob_start();
      $r['md5']=md5_file($fp); $r['versija']=get_file_data($fp,['v'=>'Version'])['v']; $r['hb']=$hb();
      if(!defined('WOOCOMMERCE_CART')) define('WOOCOMMERCE_CART',true);
      wc_load_cart(); $rc=new ReflectionClass('Petshop_FBT'); $o=$rc->newInstanceWithoutConstructor(); $jp=$rc->getMethod('juosta_pasiulymas'); $jp->setAccessible(true);
      $nm=function($h){ return trim(preg_replace('/\s+/',' ',strip_tags(str_replace('<br>',' | ',$h)))); };
      foreach([[18590,1],[18369,1],[16463,1],[18599,4]] as $c){ $p=wc_get_product($c[0]); $key=md5('t'.$c[0]);
        WC()->cart->set_cart_contents([$key=>['key'=>$key,'product_id'=>$c[0],'variation_id'=>0,'variation'=>[],'quantity'=>$c[1],'data'=>$p,'data_hash'=>'']]);
        $tot=round((float)$p->get_price()*$c[1],2); WC()->cart->set_subtotal($tot); WC()->cart->set_subtotal_tax(0); WC()->cart->set_discount_total(0); WC()->cart->set_discount_tax(0);
        $o2=$rc->newInstanceWithoutConstructor();
        $row=['krepselis'=>$c[1].' × '.html_entity_decode(get_the_title($c[0])),'suma'=>$tot,'truksta'=>round(max(0,30-$tot),2)];
        foreach([round(max(0,30-$tot),2),1.00,3.00] as $g){ $row['g'.$g]=$nm($jp->invoke($o2,$g)); }
        $lvl=ob_get_level(); ob_start(); $jf=$rc->getMethod('juosta'); $jf->invoke($o2); $h=''; while(ob_get_level()>$lvl) $h=ob_get_clean().$h; $row['juosta_html']=(bool)strpos($h,'petshop-fbt-juosta'); $row['juosta_tekstas']=mb_substr($nm($h),0,260);
        $r['testai'][]=$row; }
      WC()->cart->set_cart_contents([]);
      while(ob_get_level()>$L0) ob_end_clean();
      $log=dirname(untrailingslashit(ABSPATH)).'/logs/php_error.log'; if(is_file($log)){ $t=@file($log); $t=$t?array_slice($t,-300):[]; $r['php_log_fbt']=array_values(array_slice(array_filter($t,function($l){ return stripos($l,'petshop-fbt')!==false && strpos($l,date('d-M-Y'))!==false; }),-8)); }
    }
    if($f==='9'){ if(!is_file($bak)) throw new Exception('bak nėra'); copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['md5']=md5_file($fp); sleep(1); $r['hb']=$hb(); }
  }catch(Throwable $e){ $r['KLAIDA']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit;
}, 1);
